    private static final int[] OPPOSITE = {5, 3, 4, 1, 2, 0};

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();

        int[][] faces = new int[n][6];
        int[][] position = new int[n][7];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                faces[i][j] = fs.nextInt();
                position[i][faces[i][j]] = j;
            }
        }

        int answer = 0;
        for (int startingBottom = 1; startingBottom <= 6; startingBottom++) {
            int bottom = startingBottom;
            int sum = 0;

            for (int i = 0; i < n; i++) {
                int bottomIndex = position[i][bottom];
                int topIndex = OPPOSITE[bottomIndex];
                int top = faces[i][topIndex];

                int bestSide = 0;
                for (int j = 0; j < 6; j++) {
                    if (j != bottomIndex && j != topIndex) {
                        bestSide = Math.max(bestSide, faces[i][j]);
                    }
                }

                sum += bestSide;
                bottom = top;
            }

            answer = Math.max(answer, sum);
        }

        System.out.println(answer);
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}
